import json

def count_evictions(doc, window_title):
    # Find the task log section for the window
    log_title = f"{window_title}: Task log"
    node = None
    for n in doc["nodes"]:
        if n["title"] == log_title:
            node = n
            break

    if not node:
        return "Section not found"

    evictions = 0
    for row in node["table"]["rows"]:
        # The event column is the 8th column (index 7)
        if row[7] == "evict":
            evictions += 1
    return evictions

