# Better way to track the queue
def simulate_queue(chapter, target_time):
    node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(node)
    queue = []
    running = set()

    for row_idx, row in rows:
        t = int(row['time'])
        if t > target_time:
            break

        tid = row['task']
        event = row['event']

        if event == 'submit':
            queue.append(row)
        elif event == 'start':
            if tid in [r['task'] for r in queue]:
                queue = [r for r in queue if r['task'] != tid]
            running.add(tid)
        elif event == 'finish':
            if tid in running:
                running.remove(tid)
        elif event in ['evict', 'fail']:
            if tid in running:
                running.remove(tid)
            # Find the submission row for this task
            submit_row = next(r for r in rows if r['task'] == tid and r['event'] == 'submit')
            queue.append(submit_row)

    return queue

