log = get_task_log("Cell window 14")

# Find tasks running at time 359 before the scheduling round
running_tasks = {} # machine -> list of tasks
for row_idx, row in enumerate(log):
    r = row[1]
    t = int(r['time'])
    if t >= 359:
        # We only care about the state just before time 359's scheduling round.
        # The scheduling round happens after finishes, failures, returns, and submissions.
        # However, we can just simulate up to 358 and then check what's running.
        break

    event = r['event']
    task = r['task']
    machine = r['machine']

    if event == 'start':
        running_tasks.setdefault(machine, []).append(task)
    elif event == 'finish':
        if machine in running_tasks and task in running_tasks[machine]:
            running_tasks[machine].remove(task)
    elif event == 'evict' or event == 'fail':
        if machine in running_tasks and task in running_tasks[machine]:
            running_tasks[machine].remove(task)

# Now we need to handle the events at time 359 BEFORE the scheduling round.
# 1. Finishes
# 2. Failures
# 3. Returns
# 4. Submissions
for row_idx, row in enumerate(log):
    r = row[1]
    t = int(r['time'])
    if t < 359:
        continue
    if t > 359:
        break

    event = r['event']
    task = r['task']
    machine = r['machine']

    if event == 'finish':
        if machine in running_tasks and task in running_tasks[machine]:
            running_tasks[machine].remove(task)
    elif event == 'fail':
        # The failure of a machine removes all tasks on it.
        # Actually the task log lists 'fail' events for each task.
        if machine in running_tasks and task in running_tasks[machine]:
            running_tasks[machine].remove(task)
    # Submissions don't change running tasks.

