def get_waiting_tasks(chapter, time):
    node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(node)
    submitted = set()
    started = set()
    finished = set()
    evicted = set()
    failed = set()

    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        tid = row['task']
        event = row['event']
        if event == 'submit':
            submitted.add(tid)
        elif event == 'start':
            started.add(tid)
        elif event == 'finish':
            finished.add(tid)
        elif event == 'evict':
            evicted.add(tid)
        elif event == 'fail':
            failed.add(tid)

    # A task is waiting if it has been submitted and is not currently running.
    # Current running = started - finished - evicted - failed
    running = started - finished - evicted - failed
    waiting = submitted - running - finished
    return waiting

