def get_queue_at_time(window, time):
    log_node = node_by_title(doc, f"{window}: Task log")
    rows = table_rows(log_node)
    submitted = []
    started = set()
    finished = set()

    for idx, row in rows:
        t = int(row['time'])
        if t > time:
            break
        tid = row['task']
        if row['event'] == 'submit':
            submitted.append(row)
        elif row['event'] == 'start':
            started.add(tid)
        elif row['event'] == 'finish':
            finished.add(tid)
        elif row['event'] == 'fail' or row['event'] == 'evict':
            if tid in started:
                started.remove(tid)

    queue = [row for row in submitted if row['task'] not in started]
    # Sort by priority (desc), then submit time (asc), then task id (asc)
    queue.sort(key=lambda x: (-int(x['priority']), int(x['time']), x['task']))
    return queue

